purposes=[('Determine whether controls are effective','ตรวจว่ามาตรการได้ผลหรือไม่'),('Identify weaknesses and gaps','หาจุดอ่อนและช่องว่าง'),('Track security performance over time','ติดตามผลงานตามเวลา'),('Support risk-based decision-making','สนับสนุนการตัดสินใจตามความเสี่ยง'),('Demonstrate compliance','แสดงหลักฐาน Compliance'),('Communicate security status to management','สื่อสารสถานะให้ผู้บริหาร'),('Identify areas requiring improvement','ระบุส่วนที่ต้องปรับปรุง')]
add('slide-01-measure-for-a-decision',p('Choose the decision before the number.','เลือกคำถามที่ต้องตัดสินใจก่อนเลือกตัวเลข'),p('A security metric is a measurable value used to assess an activity, process or control.','Security metric คือค่าที่วัดได้เพื่อประเมินกิจกรรม กระบวนการ หรือ Control'),[[p(a,b),p('Connect the measure to a specific objective','เชื่อมสิ่งที่วัดกับเป้าหมายที่ชัด'),p('A number is useful when the audience can interpret and act on it.','ตัวเลขมีประโยชน์เมื่อผู้รับตีความและนำไปใช้ได้')]for a,b in purposes],p('Measuring and monitoring help determine whether security objectives are being achieved. The source gives seven purposes: assess controls, find weaknesses, track performance, support risk-based decisions, demonstrate compliance, communicate to management and identify improvements. General examples include the number of incidents, number of vulnerabilities, percentage of systems patched, Mean Time to Detect (MTTD) and Mean Time to Respond (MTTR). A useful metric should be relevant, measurable, consistent and meaningful to its audience. Start with the business question, identify suitable evidence and decide who will respond; collecting more numbers alone does not establish effectiveness.','การวัดและติดตามช่วยดูว่าบรรลุเป้าหมาย Security หรือไม่ ต้นฉบับให้เจ็ดจุดมุ่งหมาย ได้แก่ ประเมิน Control หาจุดอ่อน ติดตามผลงาน สนับสนุนการตัดสินใจตามความเสี่ยง แสดงหลักฐาน Compliance สื่อสารกับผู้บริหาร และหาส่วนปรับปรุง ตัวอย่างทั่วไปคือจำนวน Incident จำนวนช่องโหว่ เปอร์เซ็นต์ระบบที่ Patch, Mean Time to Detect (MTTD) และ Mean Time to Respond (MTTR) Metric ที่ดีควรเกี่ยวข้อง วัดได้ สอดคล้องกัน และมีความหมายต่อผู้รับ ให้เริ่มจากคำถามธุรกิจ เลือกหลักฐานที่เหมาะ และกำหนดใครจะดำเนินการ ไม่ใช่เก็บตัวเลขมากแล้วสรุปว่าได้ผล'),[p('Relevance connects the measure to a control or business question.','Relevance เชื่อมสิ่งที่วัดกับ Control หรือคำถามธุรกิจ'),p('Consistency enables meaningful comparison over time.','Consistency ช่วยให้เทียบข้ามเวลาได้มีความหมาย'),p('A named audience and action make the measure useful.','รู้ผู้รับและการดำเนินการทำให้ Metric ใช้ประโยชน์ได้')],p('Question → evidence → responsible action.','คำถาม → หลักฐาน → ผู้รับผิดชอบดำเนินการ'))
add('slide-02-denominator-and-window',p('“90% patched” needs a population and a date.','“Patch แล้ว 90%” ต้องรู้ว่าจากกลุ่มใดและเมื่อใด'),p('Illustrative snapshot: 18 of 20 in-scope systems meet the stated patching requirement.','ตัวอย่าง ณ เวลาที่วัด: 18 จาก 20 ระบบในขอบเขตผ่านข้อกำหนด Patch ที่ระบุ'),[
[p('Numerator','ตัวเศษ'),p('18 systems meeting the requirement','18 ระบบที่ผ่านข้อกำหนด'),p('Use verified evidence at the same snapshot date.','ใช้หลักฐานที่ตรวจสอบ ณ วันเดียวกัน')],
[p('Denominator','ตัวส่วน'),p('20 in-scope systems assessed','20 ระบบในขอบเขตที่ตรวจ'),p('State exclusions and coverage; missing data is not automatically compliant.','บอกส่วนที่ยกเว้นและความครอบคลุม ข้อมูลหายไม่ได้แปลว่าผ่าน')],
[p('Result and limits','ผลและข้อจำกัด'),p('18 / 20 × 100 = 90%','18 / 20 × 100 = 90%'),p('If the denominator is zero, report no applicable data rather than invent a percentage.','หากตัวส่วนเป็นศูนย์ ให้รายงานว่าไม่มีข้อมูลที่ใช้คำนวณ ไม่สร้างเปอร์เซ็นต์')]],p('A percentage is a relationship, not a complete conclusion. In this authored example,18 compliant systems divided by20 assessed in-scope systems gives90%. Define what compliant means, the population, snapshot date, evidence source and exclusions before comparing periods. If the asset inventory grows or a scanner misses critical systems, a changed percentage may reflect changed coverage rather than improvement. Report unknowns honestly. A zero denominator does not produce a meaningful compliance rate. These measurement details support the source requirements for consistent, relevant and meaningful metrics; they do not introduce an organization-independent target.','เปอร์เซ็นต์เป็นความสัมพันธ์ ไม่ใช่ข้อสรุปทั้งหมด ตัวอย่างแต่งนี้ใช้ 18 ระบบที่ผ่าน หาร 20 ระบบในขอบเขตที่ตรวจ ได้ 90% ต้องกำหนดว่าผ่านหมายถึงอะไร ประชากร วันวัด แหล่งหลักฐาน และส่วนที่ยกเว้นก่อนเทียบข้ามงวด หาก Inventory เพิ่มหรือ Scanner ไม่พบระบบสำคัญ เปอร์เซ็นต์อาจเปลี่ยนเพราะความครอบคลุม ไม่ใช่ผลงานดีขึ้น ต้องรายงานสิ่งที่ยังไม่ทราบอย่างตรงไปตรงมา ตัวส่วนศูนย์ไม่ให้ Compliance rate ที่มีความหมาย รายละเอียดเหล่านี้ช่วยให้ Metric สอดคล้อง เกี่ยวข้อง และใช้ประโยชน์ได้ ไม่ได้กำหนดเป้าหมายเดียวให้ทุกองค์กร'),[p('Use matching populations and dates for numerator and denominator.','ใช้ประชากรและวันวัดให้ตรงกันระหว่างตัวเศษกับตัวส่วน'),p('Separate unknown coverage from an observed compliant result.','แยกข้อมูลครอบคลุมที่ไม่ทราบออกจากผลว่าผ่าน'),p('Document calculation and evidence so another reviewer can reproduce it.','บันทึกวิธีคำนวณกับหลักฐานให้ผู้ตรวจอื่นทำซ้ำได้')],p('A rate is only as clear as its definition.','อัตราชัดเจนได้เมื่อคำนิยามชัด'))
groups=[('Vulnerability Management','Vulnerability Management','% critical vulnerabilities remediated within the required timeframe','% ช่องโหว่ Critical ที่แก้ภายในเวลาที่กำหนด'),('Incident Response','Incident Response','Mean Time to Respond','Mean Time to Respond'),('Security Awareness','Security Awareness','% employees completing awareness training','% พนักงานที่เรียน Awareness ครบ'),('Patch Management','Patch Management','% systems meeting patch requirements','% ระบบที่ผ่านข้อกำหนด Patch')]
add('slide-03-detection-and-response-boundaries',p('Define where each response clock starts and stops.','กำหนดจุดเริ่มและจุดจบของเวลาตอบสนอง'),p('MTTD and MTTR are averages over defined events, not guarantees for the next incident.','MTTD และ MTTR เป็นค่าเฉลี่ยของเหตุที่กำหนด ไม่รับประกันเหตุครั้งหน้า'),[[p(a,b),p(c,d),p('Specify the event scope and evidence used.','ระบุขอบเขตเหตุและหลักฐานที่ใช้')]for a,b,c,d in groups],p('MTTD means Mean Time to Detect. This course uses MTTR as Mean Time to Respond; other organizations use the acronym differently, so explicitly define it before comparing values. For a local measure, define the incident start, detection and response milestones, then average comparable durations across a stated set of incidents. An average can hide a severe outlier and depends on what was observed or missed. Do not silently redefine response as complete recovery. The source also applies metrics to vulnerability remediation, awareness completion and patching requirements; each needs its own population, timeframe and interpretation.','MTTD หมายถึง Mean Time to Detect ส่วนบทเรียนนี้ใช้ MTTR ว่า Mean Time to Respond องค์กรอื่นอาจขยายคำต่างกัน จึงต้องกำหนดก่อนเทียบค่า เมื่อสร้างตัววัดภายใน ให้ระบุเวลาเริ่มเหตุ จุดตรวจพบ และจุดตอบสนอง แล้วหาค่าเฉลี่ยช่วงเวลาที่เทียบกันได้จากกลุ่ม Incident ที่ระบุ ค่าเฉลี่ยอาจซ่อนเหตุที่ช้ามาก และขึ้นกับสิ่งที่ตรวจพบหรือพลาด อย่าเปลี่ยนความหมาย Respond เป็นกู้คืนเสร็จทั้งหมดโดยไม่บอก ต้นฉบับยังใช้ Metric กับการแก้ช่องโหว่ การเรียน Awareness และข้อกำหนด Patch ซึ่งแต่ละเรื่องต้องมีประชากร ช่วงเวลา และวิธีตีความของตน'),[p('Choose and document the response milestone before collecting durations.','เลือกและบันทึกจุดตอบสนองก่อนเก็บระยะเวลา'),p('Report the incident population and inspect outliers.','รายงานกลุ่ม Incident และตรวจเหตุที่ผิดจากกลุ่มมาก'),p('A training-completion metric measures participation, not every secure behaviour.','ตัววัดเรียนครบวัดการเข้าร่วม ไม่ใช่พฤติกรรมปลอดภัยทุกด้าน')],p('Compare like definitions and comparable events.','เทียบคำนิยามเดียวกันและเหตุที่เทียบกันได้'))
kris=[('Critical unpatched vulnerabilities','ช่องโหว่ Critical ที่ยังไม่ Patch','Exposure remains open','ยังมีความเสี่ยงเปิดอยู่'),('Privileged accounts without MFA','บัญชีสิทธิ์สูงที่ไม่มี MFA','Privileged access may be less protected','การเข้าถึงสิทธิ์สูงอาจป้องกันไม่พอ'),('Failed security controls','Control ที่ทำงานล้มเหลว','Expected protection may be missing','การป้องกันที่คาดหวังอาจขาด'),('Increase in phishing reports','รายงาน Phishing เพิ่ม','Investigate threats and reporting behaviour','ตรวจทั้งภัยและพฤติกรรมรายงาน'),('Unsupported systems','ระบบที่หมดการสนับสนุน','Support and remediation options may be limited','ทางสนับสนุนและแก้ไขอาจจำกัด'),('Critical systems without tested backups','ระบบสำคัญที่ไม่มี Backup ที่ทดสอบแล้ว','Recoverability is unproven','ยังไม่พิสูจน์ว่ากู้คืนได้')]
add('slide-04-kri-exposure',p('A KRI signals exposure that needs attention.','KRI ชี้ความเสี่ยงที่ควรติดตาม'),p('Use a risk-related measure to decide where to investigate or act.','ใช้สิ่งที่วัดซึ่งเกี่ยวกับความเสี่ยง เพื่อเลือกว่าจะตรวจหรือดำเนินการที่ใด'),[[p(a,b),p(c,d),p('Interpret with scope, trend and business impact.','ตีความพร้อมขอบเขต แนวโน้ม และผลต่อธุรกิจ')]for a,b,c,d in kris],p('A Key Risk Indicator (KRI) provides an indication of changing risk so the organization can investigate before a significant loss. The source examples are unpatched critical vulnerabilities, privileged accounts without MFA, failed controls, increased phishing reports, unsupported systems and critical systems without tested backups. A KRI is not a prediction that an incident must occur. For example,more reports may reflect more attacks or improved reporting. The official Domain 2 AI guidance also supports AI-specific KRIs: a defined measure of deteriorating model performance (model drift) may flag an operational concern in a critical service. Select validated measures and escalation criteria in context; no universal numeric threshold is implied.','Key Risk Indicator (KRI) ให้สัญญาณความเสี่ยงที่เปลี่ยน เพื่อให้องค์กรตรวจสอบก่อนเกิดความเสียหายสำคัญ ตัวอย่างต้นฉบับคือช่องโหว่ Critical ที่ยังไม่ Patch บัญชีสิทธิ์สูงไม่มี MFA, Control ล้มเหลว รายงาน Phishing เพิ่ม ระบบหมด Support และระบบสำคัญไม่มี Backup ที่ทดสอบแล้ว KRI ไม่ได้ทำนายว่าจะต้องเกิดเหตุ เช่น รายงานเพิ่มอาจมาจากโจมตีเพิ่มหรือคนรายงานดีขึ้น แนวทาง AI ของ Domain 2 ยังรองรับ KRI เฉพาะ AI เช่น ตัววัดประสิทธิภาพ Model ที่ลดลงหรือ Model drift อาจเตือนปัญหาการดำเนินงานในบริการสำคัญ ต้องเลือกตัววัดที่ตรวจสอบแล้วและเกณฑ์ส่งต่อให้ตรงบริบท ไม่ได้มีค่าตัวเลขสากล'),[p('A KRI helps prioritize review; it is not a full risk assessment.','KRI ช่วยจัดลำดับตรวจ แต่ไม่ใช่ Risk assessment ทั้งหมด'),p('Criticality and compensating safeguards affect interpretation.','ความสำคัญของระบบและมาตรการชดเชยมีผลต่อการตีความ'),p('AI-specific indicators need an owner, data quality and a response process.','ตัวชี้วัด AI ต้องมีเจ้าของ คุณภาพข้อมูล และขั้นตอนตอบสนอง')],p('An indicator starts a question; context supports the answer.','Indicator เริ่มคำถาม ส่วนบริบทช่วยตอบ'))
add('slide-05-kpi-performance-objective',p('A KPI asks how well we meet a stated objective.','KPI ถามว่าเราทำได้ตามเป้าหมายเพียงใด'),p('Source example: percentage of critical vulnerabilities patched within 15 days.','ตัวอย่างต้นฉบับ: เปอร์เซ็นต์ช่องโหว่ Critical ที่ Patch ภายใน 15 วัน'),[
[p('Objective','เป้าหมาย'),p('Patch critical vulnerabilities within 15 days','Patch ช่องโหว่ Critical ภายใน 15 วัน'),p('The time limit is the course example, not a universal rule.','ช่วงเวลานี้เป็นตัวอย่างต้นฉบับ ไม่ใช่กฎสำหรับทุกองค์กร')],
[p('Illustrative result','ผลตัวอย่าง'),p('18 of 20 eligible findings met the deadline: 90%','18 จาก 20 รายการที่เข้าเกณฑ์ทันเวลา: 90%'),p('Use a defined cohort whose 15-day deadlines fall in the reporting period.','ใช้กลุ่มที่กำหนด โดยเส้นตาย 15 วันอยู่ในงวดรายงาน')],
[p('Illustrative target','เป้าหมายตัวอย่าง'),p('95% target → 90% actual → investigate the gap','เป้า 95% → ผล 90% → ตรวจช่องว่าง'),p('The 95% target is authored for this example; examine overdue critical findings as well.','เป้า 95% แต่งเพื่ออธิบายตัวอย่าง ต้องดูรายการ Critical เกินกำหนดด้วย')]],p('A Key Performance Indicator (KPI) measures progress toward a specific performance objective. The original example is the percentage of critical vulnerabilities patched within15days. For the authored calculation, take a defined cohort of20 eligible findings with deadlines in the reporting period;18 met their deadlines, so performance is90%. An illustrative95% target is not met. Define the cohort so new findings not yet due are not confused with missed deadlines, and do not silently exclude still-open overdue findings. The percentage should lead to investigation and assigned action. It does not alone prove that residual exposure or business risk is acceptable.','Key Performance Indicator (KPI) วัดความก้าวหน้าต่อเป้าหมายผลงานที่กำหนด ต้นฉบับยกเปอร์เซ็นต์ช่องโหว่ Critical ที่ Patch ภายใน 15 วัน ตัวอย่างคำนวณแต่งใช้กลุ่ม 20 รายการที่เส้นตายอยู่ในงวดรายงาน โดย 18 รายการทันเวลา จึงได้ 90% ซึ่งยังไม่ถึงเป้าตัวอย่าง 95% ต้องกำหนดกลุ่มให้รายการใหม่ที่ยังไม่ถึงเส้นตายไม่ปนกับรายการที่พลาด และไม่ตัดรายการเกินกำหนดที่ยังเปิดออกอย่างเงียบๆ เปอร์เซ็นต์ควรนำไปสู่การตรวจและมอบหมายการแก้ ไม่ได้พิสูจน์ด้วยตัวเองว่าความเสี่ยงที่เหลือยอมรับได้'),[p('KPI focuses on performance against an objective.','KPI เน้นผลงานเทียบเป้าหมาย'),p('A deadline cohort must include eligible overdue items.','กลุ่มตามเส้นตายต้องรวมรายการเกินกำหนดที่เข้าเกณฑ์'),p('Pair progress with relevant risk evidence.','ดูผลงานควบคู่หลักฐานความเสี่ยงที่เกี่ยวข้อง')],p('A better percentage does not settle every risk question.','เปอร์เซ็นต์ดีขึ้นไม่ได้ตอบความเสี่ยงทุกเรื่อง'))
add('slide-06-interpretation-and-indicator-role',p('More reports can have more than one explanation.','รายงานเพิ่มอาจอธิบายได้มากกว่าหนึ่งแบบ'),p('Interpret a trend before turning it into a conclusion or a score.','ตีความแนวโน้มก่อนเปลี่ยนเป็นข้อสรุปหรือคะแนน'),[
[p('Observed trend','แนวโน้มที่วัดได้'),p('Phishing reports rise from 10 to 20','รายงาน Phishing เพิ่มจาก 10 เป็น 20'),p('Authored equal-period counts; not automatically a change in incident frequency.','จำนวนตัวอย่างจากงวดยาวเท่ากัน ไม่ได้แปลว่าความถี่ Incident เปลี่ยนทันที')],
[p('Possible explanations','คำอธิบายที่เป็นไปได้'),p('More attacks or better reporting','โจมตีมากขึ้น หรือรายงานดีขึ้น'),p('Check confirmed threats, reporting coverage and changed definitions.','ตรวจภัยที่ยืนยัน ความครอบคลุมรายงาน และคำนิยามที่เปลี่ยน')],
[p('Role and timing','บทบาทกับเวลา'),p('Risk / performance; leading / lagging','ความเสี่ยง / ผลงาน; Leading / Lagging'),p('KPI/KRI describe intended use; leading/lagging describe temporal relationships. They are not interchangeable classifications.','KPI/KRI ดูจุดประสงค์การใช้ ส่วน Leading/Lagging ดูความสัมพันธ์ด้านเวลา ไม่ใช่หมวดที่แทนกันตรงๆ')]],p('An observed metric does not explain its own cause. More phishing reports may indicate more suspicious messages, better awareness, easier reporting or a changed reporting scope. Confirm the definitions and look for corroborating evidence before declaring risk higher or lower. Leading indicators concern conditions preceding an outcome; lagging indicators summarize outcomes already observed. This distinction is supplementary context, not a rule equating every KRI with a leading measure and every KPI with a lagging one. A metric’s risk or performance role depends on the question it supports. Use uncertainty and data quality as part of the interpretation rather than hide them in a single green status.','Metric ที่วัดได้ไม่ได้อธิบายสาเหตุด้วยตัวเอง รายงาน Phishing เพิ่มอาจมาจากข้อความน่าสงสัยมากขึ้น Awareness ดีขึ้น รายงานง่ายขึ้น หรือขอบเขตเปลี่ยน ต้องยืนยันคำนิยามและหาหลักฐานประกอบก่อนสรุปความเสี่ยงสูงหรือต่ำ Leading indicator สนใจเงื่อนไขก่อนผลเกิด ส่วน Lagging indicator สรุปผลที่เกิดแล้ว ความต่างนี้เป็นบริบทเสริม ไม่ใช่กฎจับ KRI ทุกตัวเป็น Leading หรือ KPI ทุกตัวเป็น Lagging บทบาทด้านความเสี่ยงหรือผลงานขึ้นกับคำถามที่ใช้ ต้องแสดงความไม่แน่นอนและคุณภาพข้อมูลในการตีความ แทนซ่อนไว้ในสถานะสีเขียวค่าเดียว'),[p('A trend is evidence to investigate, not proof of one cause.','แนวโน้มเป็นหลักฐานให้ตรวจ ไม่ใช่ข้อพิสูจน์สาเหตุเดียว'),p('Changed definitions can invalidate a period-to-period comparison.','คำนิยามที่เปลี่ยนอาจทำให้เทียบข้ามงวดไม่ได้'),p('Choose measures for the intended decision and audience.','เลือกสิ่งที่วัดให้ตรงการตัดสินใจและผู้รับ')],p('Interpret the evidence before choosing the response.','ตีความหลักฐานก่อนเลือกวิธีตอบสนอง'))
rows=[
[p('A','A'),p('Declare low risk because the patch KPI improved.','ประกาศว่าความเสี่ยงต่ำเพราะ Patch KPI ดีขึ้น'),p('Improved performance on one objective does not establish that privileged access or other exposures are acceptable.','ผลงานดีขึ้นในเป้าหมายเดียวไม่พิสูจน์ว่า Privileged access หรือความเสี่ยงอื่นยอมรับได้')],
[p('B','B'),p('Rename every measure a KPI and hide exposure counts.','เปลี่ยนชื่อทุกตัวเป็น KPI แล้วซ่อนจำนวนความเสี่ยง'),p('Changing labels removes useful context rather than fixing the exposed accounts or overdue vulnerabilities.','เปลี่ยนชื่อทำให้บริบทสำคัญหาย ไม่ได้แก้บัญชีที่เสี่ยงหรือช่องโหว่เกินกำหนด')],
[p('C','C'),p('Validate the definitions, review critical exposure and assign action owners.','ตรวจนิยาม ทบทวนความเสี่ยงสำคัญ และมอบหมายคนดำเนินการ'),p('Use both the KPI and the KRI, with consistent scope and business impact. Investigate unprotected privileged accounts and overdue critical findings with responsible owners.','ใช้ KPI และ KRI ร่วมกันด้วยขอบเขตที่สอดคล้องและผลต่อธุรกิจ ตรวจบัญชีสิทธิ์สูงที่ป้องกันไม่พอกับรายการ Critical เกินกำหนดร่วมกับเจ้าของ')],
[p('D','D'),p('Assume more phishing reports always mean more successful attacks.','ถือว่ารายงาน Phishing เพิ่มแปลว่าโจมตีสำเร็จเพิ่มเสมอ'),p('Reports are not confirmed successful incidents. Check threat activity, reporting behaviour and coverage.','รายงานไม่ใช่ Incident โจมตีสำเร็จที่ยืนยันแล้ว ต้องตรวจภัย พฤติกรรมรายงาน และความครอบคลุม')]]
add('slide-07-metrics-decision',p('The patch KPI improved, but privileged accounts lack MFA.','Patch KPI ดีขึ้น แต่บัญชีสิทธิ์สูงยังไม่มี MFA'),p('How should the team interpret these two pieces of evidence?','ทีมควรตีความหลักฐานสองส่วนนี้อย่างไร?'),rows,p('This authored decision combines performance and exposure evidence. A patch KPI can improve while a KRI still flags privileged accounts without MFA. Validate the source, population, reporting period and objective before interpretation, then investigate critical exposures with their owners. The KPI answers a performance question; the KRI helps ask a risk question. They should support a responsible action rather than compete for a single favourable status. More phishing reports also need context and are not automatically successful attacks. No fixed percentage establishes acceptable risk for all organizations or replaces the organization’s risk assessment and decision authority.','สถานการณ์แต่งนี้รวมหลักฐานผลงานกับความเสี่ยง Patch KPI อาจดีขึ้นขณะที่ KRI ยังชี้บัญชีสิทธิ์สูงไม่มี MFA ต้องตรวจแหล่งข้อมูล ประชากร งวดรายงาน และเป้าหมายก่อนตีความ แล้วตรวจความเสี่ยงสำคัญร่วมกับเจ้าของ KPI ตอบเรื่องผลงาน ส่วน KRI ช่วยตั้งคำถามด้านความเสี่ยง ทั้งสองควรสนับสนุนการดำเนินการที่รับผิดชอบ ไม่แข่งกันแสดงสถานะที่ดูดีค่าเดียว รายงาน Phishing เพิ่มก็ต้องมีบริบท ไม่เท่ากับโจมตีสำเร็จเสมอ ไม่มีเปอร์เซ็นต์ตายตัวที่บอกความเสี่ยงยอมรับได้ทุกองค์กรหรือแทน Risk assessment กับผู้มีอำนาจตัดสินใจ'),[p('Check data quality before acting on a trend.','ตรวจคุณภาพข้อมูลก่อนลงมือจากแนวโน้ม'),p('Performance and exposure measures answer different questions.','ผลงานกับความเสี่ยงตอบคำถามต่างกัน'),p('Assign a responsible owner to investigate and follow up.','มอบหมายเจ้าของให้ตรวจและติดตาม')],p('Use the evidence together to support a decision.','ใช้หลักฐานร่วมกันเพื่อสนับสนุนการตัดสินใจ'),True)
l=lesson('lesson-d2-07-security-metrics-kpi-kri','2.4',p('Security Metrics, KPIs & KRIs','Security Metrics, KPI และ KRI'),p('Define useful measures, interpret time and percentage metrics, and distinguish performance from risk evidence.','กำหนด Metric ที่ใช้ได้ ตีความเวลา/เปอร์เซ็นต์ และแยกหลักฐานผลงานจากความเสี่ยง'),[p('Explain the source metrics, applied domains and six KRI examples.','อธิบาย Metric ตามต้นฉบับ ด้านที่ประยุกต์ และ KRI หกตัวอย่าง'),p('Interpret a defined 15-day patch KPI with scope, data quality and uncertainty.','ตีความ Patch KPI 15 วัน พร้อมขอบเขต คุณภาพข้อมูล และความไม่แน่นอน')],s,'Actual S29–S33, notes§§17–20, summary metrics and transcript measurement section. Q8 privileged accounts withoutMFA; Q9 15-day patchKPI. Official AI model-drift/KRI supplement.',[{'id':'nist-sp-800-55v1','title':'NIST SP800-55 Volume1 — Identifying and Selecting Measures','authority':'technical-primary','url':'https://csrc.nist.gov/pubs/sp/800/55/v1/final','locator':'§3.1 documentation/data quality and leading/lagging definitions; supplementary context.'}])
publish(l);wire('security-metrics-presentations','SecurityMetrics','security-metrics');print('Authored/published seven bilingual L7 slides')
